#include <stdio.h>
#include "hud_row_pool.h"
#define CHECK(x) do{if(!(x)){fprintf(stderr,"failed line %u\n",__LINE__);return 1;}}while(0)
int main(int argc,char**argv){CHECK(argc>1);size_t n=160*sizeof(NFHudLayerRow);uint8_t*data=malloc(n),*ref=malloc(n),*out=malloc(n);CHECK(data&&ref&&out);
 for(int k=1;k<argc;k++){FILE*f=fopen(argv[k],"rb");CHECK(f&&fread(data,1,n,f)==n&&fgetc(f)==EOF);fclose(f);memcpy(ref,data,n);NFHudRowPool*p=nf_hud_pool_create(data,n,7);CHECK(p);_putenv("NF_TEST_HUD_POOL_PREVIOUS_HINT=1");NFHudRowPool*hint=nf_hud_pool_create(data,n,7);CHECK(hint&&hint->bytes==p->bytes&&!memcmp(hint,p,p->bytes));free(hint);_putenv("NF_TEST_HUD_POOL_PREVIOUS_HINT=");size_t size=p->bytes;memset(data,0,n);CHECK(nf_hud_pool_expand(p,size,7,out,n)&&!memcmp(ref,out,n));
 memset(out,0xa5,n);CHECK(!nf_hud_pool_expand(p,size,8,out,n)&&out[0]==0xa5);CHECK(!nf_hud_pool_expand(p,size-1,7,out,n)&&out[0]==0xa5);NFHudLayerRow row;memset(&row,0xa5,sizeof(row));CHECK(!nf_hud_pool_row(p,size,7,160,&row)&&((uint8_t*)&row)[0]==0xa5);
 uint32_t index=p->indices[0];p->indices[0]=p->count;CHECK(!nf_hud_pool_expand(p,size,7,out,n)&&out[0]==0xa5);p->indices[0]=index;p->payload[0]^=1;CHECK(!nf_hud_pool_expand(p,size,7,out,n)&&out[0]==0xa5);p->payload[0]^=1;CHECK(nf_hud_pool_valid(p,size,7));
 printf("HUD_POOL_EXACT file=%s full=%zu pooled=%zu unique=%u ownership_epoch_bounds_corruption=PASS\n",argv[k],n,size,p->count);free(p);
 memcpy(data,ref,n);((NFHudLayerRow*)data)[0].row=1;CHECK(!nf_hud_pool_create(data,n,7));CHECK(!nf_hud_pool_create(ref,n-1,7)&&!nf_hud_pool_create(ref,n,0));}
 memset(data,0,n);for(unsigned i=0;i<160;i++){NFHudLayerRow*r=(NFHudLayerRow*)data+i;r->refresh=99;r->row=i;r->palette[0]=(uint8_t)i;r->oam[1]=(uint8_t)(159-i);}NFHudRowPool*worst=nf_hud_pool_create(data,n,9);CHECK(worst&&worst->count==160);_putenv("NF_TEST_HUD_POOL_PREVIOUS_HINT=1");NFHudRowPool*worst_hint=nf_hud_pool_create(data,n,9);CHECK(worst_hint&&worst_hint->bytes==worst->bytes&&!memcmp(worst_hint,worst,worst->bytes));free(worst_hint);_putenv("NF_TEST_HUD_POOL_PREVIOUS_HINT=");CHECK(nf_hud_pool_expand(worst,worst->bytes,9,out,n)&&!memcmp(data,out,n));printf("HUD_POOL_WORST_CASE rows=160 unique=160 exact=PASS bytes=%zu\n",worst->bytes);free(worst);
 for(unsigned i=0;i<160;i++){NFHudLayerRow*r=(NFHudLayerRow*)data+i;memset(r->obj_vram,0,NF_HUD_POOL_PAYLOAD);}NFHudRowPool*one=nf_hud_pool_create(data,n,9);CHECK(one&&one->count==1);CHECK(nf_hud_pool_expand(one,one->bytes,9,out,n)&&!memcmp(data,out,n));printf("HUD_POOL_IDENTICAL_PAYLOAD rows=160 unique=1 exact=PASS bytes=%zu\n",one->bytes);free(one);
 free(data);free(ref);free(out);return 0;}
